// --- Active language (module-level; read at render time) ---------------------

export type Lang = "bn" | "en";

let _lang: Lang = "bn";

/** Set the active UI language. Called by LanguageContext; takes effect on the
 *  next render of any component that reads STR / a label fn. */
export function setActiveLang(lang: Lang): void {
  _lang = lang;
}

/** The current active language. */
export function getActiveLang(): Lang {
  return _lang;
}

/** Pick the BN or EN variant of a value by the active language. */
const pick = <T>(bn: T, en: T): T => (_lang === "en" ? en : bn);

const BN_DIGITS = ["০", "১", "২", "৩", "৪", "৫", "৬", "৭", "৮", "৯"];

/** Render a number with Bangla numerals in Bangla mode, Latin digits in English
 *  (NFR-5). Kept named `bnNum` for call-site stability. */
export function bnNum(n: number | string): string {
  if (_lang === "en") return String(n);
  return String(n).replace(/[0-9]/g, (d) => BN_DIGITS[Number(d)]);
}

const DASH = "—";

/** A date-group header for the pending-work lists: weekday + localized-digit date,
 *  e.g. "শনিবার · ২০২৬-০৬-১৬" (bn) / "Saturday · 2026-06-16" (en). */
export function dateHeaderLabel(key: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(key);
  if (!m) return bnNum(key);
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  const dow = DAYS_OF_WEEK[d.getDay()];
  const wk = dow ? pick(DAY_OF_WEEK_LABELS_BN, DAY_OF_WEEK_LABELS_EN)[dow] : "";
  return wk ? `${wk} · ${bnNum(key)}` : bnNum(key);
}

/** Full date header for the Today screen (ux-audit F7): "বুধবার, ১৬ জুলাই ২০২৬" (bn) /
 *  "Wednesday, 16 July 2026" (en). Component-parses the LOCAL YYYY-MM-DD key —
 *  never `new Date(key)`, which is UTC midnight and can shift the weekday (D-#304). */
export function fullDateLabel(key: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(key);
  if (!m) return bnNum(key);
  const d = new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
  const dow = DAYS_OF_WEEK[d.getDay()];
  const wk = dow ? pick(DAY_OF_WEEK_LABELS_BN, DAY_OF_WEEK_LABELS_EN)[dow] : "";
  const datePart = `${bnNum(Number(m[3]))} ${monthLabel(Number(m[2]) - 1)} ${bnNum(Number(m[1]))}`;
  return wk ? `${wk}, ${datePart}` : datePart;
}

/** Compact localized date for a FULL ISO timestamp (createdAt etc.):
 *  "২০২৬-০৭-১৭" (bn) / "2026-07-17" (en). Unlike the YYYY-MM-DD helpers above,
 *  a full ISO string parses to the correct instant, so LOCAL components are
 *  taken after parsing (no D-#304 weekday shift). */
export function isoDateLabel(iso?: string | null): string {
  if (!iso) return DASH;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return bnNum(iso);
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return bnNum(`${y}-${m}-${dd}`);
}

/** Deterministic Dhaka (UTC+6, no DST) calendar-day KEY as ASCII "YYYY-MM-DD".
 *  Replaces `toLocaleDateString("en-CA", { timeZone: "Asia/Dhaka" })`, which routes
 *  through Hermes `Intl`/device ICU and CRASHES on some Android Go devices (owner
 *  2026-07-27). Never Bangla-numeralised — this is a key, not a display string. */
export function dhakaDateKey(input?: string | Date | null): string {
  const d = input == null ? new Date() : input instanceof Date ? input : new Date(input);
  if (Number.isNaN(d.getTime())) return "";
  const s = new Date(d.getTime() + 6 * 3600 * 1000); // shift into Dhaka, read UTC parts
  const y = s.getUTCFullYear();
  const m = String(s.getUTCMonth() + 1).padStart(2, "0");
  const dd = String(s.getUTCDate()).padStart(2, "0");
  return `${y}-${m}-${dd}`;
}

/** Compact Dhaka date+time for a full ISO timestamp: "২০২৬-০৭-১৭ ১৪:৩০".
 *  Deterministic replacement for `toLocaleString()` (device-ICU; Hermes-Intl crash
 *  vector on some Android Go devices, owner 2026-07-27). Fixed Dhaka offset — every
 *  user is in Bangladesh, so this reads the same as the old device-local time. */
export function isoDateTimeLabel(iso?: string | null): string {
  if (!iso) return DASH;
  const d = new Date(iso);
  if (Number.isNaN(d.getTime())) return bnNum(iso);
  const s = new Date(d.getTime() + 6 * 3600 * 1000);
  const y = s.getUTCFullYear();
  const mo = String(s.getUTCMonth() + 1).padStart(2, "0");
  const da = String(s.getUTCDate()).padStart(2, "0");
  const hh = String(s.getUTCHours()).padStart(2, "0");
  const mi = String(s.getUTCMinutes()).padStart(2, "0");
  return bnNum(`${y}-${mo}-${da} ${hh}:${mi}`);
}

export const subjectLabel = (code?: string | null): string =>
  (code && pick(SUBJECT_LABELS_BN, SUBJECT_LABELS_EN)[code as Subject]) || code || DASH;

/** What a print job is FOR — classwork / homework / assignment / class test / … The
 *  print queue showed the raw enum before the D-#362 history needed to sort by it. */
export const printPurposeLabel = (v?: string | null): string =>
  (v && pick(PRINT_PURPOSE_LABELS_BN, PRINT_PURPOSE_LABELS_EN)[v as PrintPurpose]) || v || DASH;

export const difficultyLabel = (v?: string | null): string =>
  (v && pick(DIFFICULTY_LABELS_BN, DIFFICULTY_LABELS_EN)[v as Difficulty]) || v || DASH;

export const paperRoleLabel = (v?: string | null): string =>
  (v && pick(PAPER_ROLE_LABELS_BN, PAPER_ROLE_LABELS_EN)[v as PaperRole]) || v || DASH;

/** Exercise family (D-#511). An unknown code — a category a newer import introduced
 *  that this build has no label for — is shown VERBATIM rather than as a dash, so the
 *  filter still works on a phone that has not been updated. */
export const questionCategoryLabel = (v?: string | null): string =>
  (v && pick(QUESTION_CATEGORY_LABELS_BN, QUESTION_CATEGORY_LABELS_EN)[v as QuestionCategory]) ||
  v ||
  DASH;

export const reviewStatusLabel = (v?: string | null): string =>
  (v && pick(REVIEW_STATUS_LABELS_BN, REVIEW_STATUS_LABELS_EN)[v as ReviewStatus]) || v || DASH;

export const curationTagLabel = (v?: string | null): string =>
  (v && pick(CURATION_TAG_LABELS_BN, CURATION_TAG_LABELS_EN)[v as CurationTag]) || v || DASH;

/** Selection-tray summary (ux-audit F6): "৫টি প্রশ্ন · ২০ নম্বর" / "5 questions · 20 marks". */
export function selectionSummaryLabel(count: number, marks: number): string {
  return _lang === "en"
    ? `${count} question${count === 1 ? "" : "s"} · ${marks} marks`
    : `${bnNum(count)}টি প্রশ্ন · ${bnNum(marks)} নম্বর`;
}

export const teacherAttendanceStatusLabel = (v?: string | null): string =>
  (v && pick(TEACHER_ATTENDANCE_STATUS_LABELS_BN, TEACHER_ATTENDANCE_STATUS_LABELS_EN)[v as TeacherAttendanceStatus]) || v || DASH;

export const reviewVerdictLabel = (v?: string | null): string =>
  (v && pick(REVIEW_VERDICT_LABELS_BN, REVIEW_VERDICT_LABELS_EN)[v as ReviewVerdict]) || v || DASH;

