export const leaveStatusLabel = (v?: string | null): string =>
  (v && pick(LEAVE_STATUS_LABELS_BN, LEAVE_STATUS_LABELS_EN)[v as LeaveStatus]) || v || DASH;

export const coverSlotStatusLabel = (v?: string | null): string =>
  (v && pick(COVER_SLOT_STATUS_LABELS_BN, COVER_SLOT_STATUS_LABELS_EN)[v as CoverSlotStatus]) || v || DASH;

/** Full day / late entry / early leave (D-#361). */
export const leaveDayPartLabel = (v?: string | null): string =>
  (v && pick(LEAVE_DAY_PART_LABELS_BN, LEAVE_DAY_PART_LABELS_EN)[v as LeaveDayPart]) || v || DASH;

/** One line describing a partial-day leave — "আগে চলে যাওয়া · পিরিয়ড ৭, ৮" — or null
 *  for a full day, so a leave card can render it unconditionally (D-#361). */
export const leavePartialSummary = (dayPart?: string | null, periods?: number[] | null): string | null => {
  if (!dayPart || dayPart === "full") return null;
  const label = leaveDayPartLabel(dayPart);
  if (!periods || periods.length === 0) return label;
  return `${label} · ${STR.hrLeavePeriodShort} ${periods.map((p) => bnNum(p)).join(", ")}`;
};

export const conductStageLabel = (v?: string | null): string =>
  (v && pick(CONDUCT_STAGE_LABELS_BN, CONDUCT_STAGE_LABELS_EN)[v as ConductStage]) || v || DASH;

export const conductRecordStatusLabel = (v?: string | null): string =>
  (v && pick(CONDUCT_RECORD_STATUS_LABELS_BN, CONDUCT_RECORD_STATUS_LABELS_EN)[v as ConductRecordStatus]) || v || DASH;

export const appraisalStatusLabel = (v?: string | null): string =>
  (v && pick(APPRAISAL_STATUS_LABELS_BN, APPRAISAL_STATUS_LABELS_EN)[v as AppraisalStatus]) || v || DASH;

export const appraisalOutcomeLabel = (v?: string | null): string =>
  (v && pick(APPRAISAL_OUTCOME_LABELS_BN, APPRAISAL_OUTCOME_LABELS_EN)[v as AppraisalOutcome]) || v || DASH;

export const grievanceStatusLabel = (v?: string | null): string =>
  (v && pick(GRIEVANCE_STATUS_LABELS_BN, GRIEVANCE_STATUS_LABELS_EN)[v as GrievanceStatus]) || v || DASH;

// HR — payroll (HR-3; prd-hr §4)
export const paymentMethodLabel = (v?: string | null): string =>
  (v && pick(PAYMENT_METHOD_LABELS_BN, PAYMENT_METHOD_LABELS_EN)[v as PaymentMethod]) || v || DASH;

export const payrollRunStatusLabel = (v?: string | null): string =>
  (v && pick(PAYROLL_RUN_STATUS_LABELS_BN, PAYROLL_RUN_STATUS_LABELS_EN)[v as PayrollRunStatus]) || v || DASH;

export const payDeductionTypeLabel = (v?: string | null): string =>
  (v && pick(PAY_DEDUCTION_TYPE_LABELS_BN, PAY_DEDUCTION_TYPE_LABELS_EN)[v as PayDeductionType]) || v || DASH;

export const payAdditionTypeLabel = (v?: string | null): string =>
  (v && pick(PAY_ADDITION_TYPE_LABELS_BN, PAY_ADDITION_TYPE_LABELS_EN)[v as PayAdditionType]) || v || DASH;

export const advanceStatusLabel = (v?: string | null): string =>
  (v && pick(ADVANCE_STATUS_LABELS_BN, ADVANCE_STATUS_LABELS_EN)[v as AdvanceStatus]) || v || DASH;

/** Taka amount with localized digits (integers plain; fractions to 2dp). */
export const money = (n: number): string => `৳ ${bnNum(Number.isInteger(n) ? n : n.toFixed(2))}`;

// HR — offboarding (HR-5; prd-hr §6)
export const offboardingTriggerLabel = (v?: string | null): string =>
  (v && pick(OFFBOARDING_TRIGGER_LABELS_BN, OFFBOARDING_TRIGGER_LABELS_EN)[v as OffboardingTrigger]) || v || DASH;

export const offboardingStatusLabel = (v?: string | null): string =>
  (v && pick(OFFBOARDING_STATUS_LABELS_BN, OFFBOARDING_STATUS_LABELS_EN)[v as OffboardingStatus]) || v || DASH;

export const clearanceItemStatusLabel = (v?: string | null): string =>
  (v && pick(CLEARANCE_ITEM_STATUS_LABELS_BN, CLEARANCE_ITEM_STATUS_LABELS_EN)[v as ClearanceItemStatus]) || v || DASH;

/** "নম্বর X–Y এর মধ্যে দিন।" / "Enter a mark between X and Y." (TrackerEntry). */
export const markRangeMsg = (min: number, max: number): string =>
  _lang === "en"
    ? `Enter a mark between ${bnNum(min)} and ${bnNum(max)}.`
    : `নম্বর ${bnNum(min)}–${bnNum(max)} এর মধ্যে দিন।`;

/** "১২/৩০ রেকর্ড হয়েছে" / "12/30 recorded" — TrackerEntry progress header (F1). */
export const trackerProgressMsg = (recorded: number, total: number): string =>
  _lang === "en"
    ? `${bnNum(recorded)}/${bnNum(total)} recorded`
    : `${bnNum(recorded)}/${bnNum(total)} রেকর্ড হয়েছে`;

/** "N জন শিক্ষার্থী এখনো রেকর্ড করা হয়নি।" — close-confirm pending line (F1). */
export const trackerPendingMsg = (n: number): string =>
  _lang === "en"
    ? `${bnNum(n)} student${n === 1 ? "" : "s"} not recorded yet.`
    : `${bnNum(n)} জন শিক্ষার্থী এখনো রেকর্ড করা হয়নি।`;

/** "৭/১০ নম্বর রেকর্ড হয়েছে" — CT save toast; full ≤ 0 → "৭ নম্বর রেকর্ড হয়েছে" (F1). */
export const scoreRecordedMsg = (score: number, full: number): string => {
  const val = full > 0 ? `${bnNum(score)}/${bnNum(full)}` : bnNum(score);
  return _lang === "en" ? `Recorded ${val} marks` : `${val} নম্বর রেকর্ড হয়েছে`;
};

